<template>
  <view v-if="recordId" class="sm-card"><view class="sm-section-head"><text class="sm-h2">{{ title }}</text><button class="sm-btn sm-btn--secondary sm-btn--small" :disabled="loading" @click="toggle">{{ loading?'加载中…':expanded?'收起':'查看修订历史' }}</button></view><text class="sm-help">旧版本只读保留；下列内容反映当时保存的事实和核对材料。</text>
    <view v-if="expanded"><text v-if="!revisions.length" class="sm-help">尚无被替换的旧版本。</text><view v-for="revision in revisions" :key="revision._id" class="sm-list-row"><view class="sm-section-head"><view><text class="sm-h3">版本 {{ revision.revision }}</text><text class="sm-help">替换时间：{{ formatDateTime(revision.replaced_at) }}<br />修改原因：{{ revision.revision_reason || '未另填' }}</text></view><button class="sm-btn sm-btn--secondary sm-btn--small" @click="selected=selected===revision._id?'':revision._id">{{ selected===revision._id?'收起内容':'展开旧版' }}</button></view>
      <view v-if="selected===revision._id" class="sm-history-content"><text class="sm-tag">历史快照 · {{ revision.snapshot.signature_status==='pending_signature'?'待签认':'按原记录保留' }}</text>
        <template v-if="kind==='daily'"><text class="sm-text">日期：{{ revision.snapshot.date }} · 核对：{{ formatDateTime(revision.snapshot.checked_at) }} · 当时零报告：{{ revision.snapshot.zero_report?'已确认':'未确认' }}</text><view v-for="category in revision.snapshot.snapshot?.categories || []" :key="category.id" class="sm-list-row"><text class="sm-h3">{{ category.id }}．{{ category.name }}</text><text v-for="(check,index) in category.checks || []" :key="index" class="sm-text">{{ check.label }}：{{ resultLabels[check.result_code] || '待完成' }}；{{ check.note || check.reason || '' }}<template v-if="check.hazard_ids?.length">；隐患 {{ check.hazard_ids.join('、') }}</template></text></view><view v-for="issue in revision.snapshot.snapshot?.issues || []" :key="issue._id" class="sm-list-row"><text class="sm-text">{{ issue.hazard_no || issue._id }}：{{ issue.issue_note }}</text></view></template>
        <template v-else-if="kind==='supplement'"><view v-for="item in revision.snapshot.items || []" :key="item.code" class="sm-list-row"><text class="sm-h3">{{ item.code }} · {{ resultLabels[item.result_code] || '待完成' }}</text><text class="sm-text">{{ item.note }} {{ item.reason }}</text><text v-for="evidence in item.evidence || []" :key="evidence.value" class="sm-help">{{ evidence.label || '证据' }}：{{ evidence.value }}</text><text v-if="item.hazard_ids?.length" class="sm-help">关联隐患：{{ item.hazard_ids.join('、') }}</text></view></template>
        <template v-else-if="kind==='config'"><text class="sm-text">启用日期：{{ revision.snapshot.enabled_from }}<br />安全员账号：{{ revision.snapshot.roles?.safety_officer?.join('、') }}<br />安全总监账号：{{ revision.snapshot.roles?.safety_director?.join('、') }}<br />主要负责人账号：{{ revision.snapshot.roles?.principal?.join('、') }}<br />适用设施：{{ revision.snapshot.special_equipment?.join('、') || '未配置' }}</text></template>
        <template v-else><view v-for="[key,label] in contentLabels" :key="key" class="sm-field"><text class="sm-field-label">{{ label }}</text><text class="sm-text">{{ ['started_at','ended_at'].includes(key)?formatDateTime(revision.snapshot.content?.[key]):revision.snapshot.content?.[key] || '未填写' }}</text></view><view v-for="(issue,index) in revision.snapshot.content?.management_issues || []" :key="`issue-${index}`" class="sm-list-row"><text class="sm-text">{{ issue.type }}：{{ issue.description }}<br />风险等级：{{ riskLabels[issue.risk_level] }}<br />责任人：{{ issue.responsible_name }} · {{ issue.due_date }}<br />措施：{{ issue.measure }}</text></view><view v-for="(decision,index) in revision.snapshot.content?.decisions || []" :key="`decision-${index}`" class="sm-list-row"><text class="sm-text">{{ decision.subject }}<br />{{ decision.department }} · {{ decision.responsible_name }} · {{ decision.due_date }}<br />落实：{{ decision.implementation || '未记录' }}</text></view></template>
      </view></view></view>
  </view>
</template>
<script setup>
import { computed,ref } from 'vue'
import { listSafetyRevisions } from '@/services/safetyManagement'
import { formatDateTime,resultLabels,showError } from './helpers'
const props=defineProps({kind:String,recordId:String,title:{type:String,default:'修订追溯'}})
const expanded=ref(false),loading=ref(false),revisions=ref([]),selected=ref('')
const weekly=[['actual_date','排查日期'],['started_at','开始时间'],['ended_at','结束时间'],['organizer','组织人'],['participants','参加人员'],['scope','范围'],['site_findings','现场结果'],['execution_evaluation','执行评价'],['repeated_problem_analysis','反复问题'],['system_gaps','制度漏洞'],['next_plan','下周计划']]
const monthly=[['actual_date','会议日期'],['started_at','开始时间'],['ended_at','结束时间'],['title','会议名称'],['location','会议地点'],['host','主持人'],['recorder','记录人'],['participants','参加人员'],['absences','缺席及原因'],['previous_decisions','上月决议落实'],['accidents_and_near_misses','事故涉险'],['safety_situation','安全形势'],['major_risks','重大风险隐患'],['special_work','专项工作'],['training','培训'],['expenditure','费用'],['emergency_management','应急管理'],['contractors','外协管理'],['causes','原因分析'],['principal_summary','主要负责人总结']]
const contentLabels=computed(()=>props.kind==='weekly'?weekly:monthly),riskLabels={general:'一般',elevated:'较大',major:'重大'}
async function toggle(){if(expanded.value){expanded.value=false;return}loading.value=true;try{const result=await listSafetyRevisions({kind:props.kind,record_id:props.recordId});revisions.value=result.revisions || [];expanded.value=true}catch(err){showError(err)}finally{loading.value=false}}
</script>
<style scoped>.sm-history-content { margin-top:18rpx; padding:20rpx; border:1rpx dashed #b8cad6; background:#f8fafc; border-radius:14rpx; }</style>
